import pandas as pd


def _to_cents(x: float) -> int:
    # Emulate DECIMAL(12,2) exact arithmetic by working in integer cents.
    return int(round(float(x) * 100))


def run(inputs: dict) -> dict:
    invoices = inputs["invoices"].copy()
    payments = inputs["payments"].copy()

    # Sort invoices: oldest due_date first, tie-break by invoice_id.
    invoices = invoices.sort_values(
        by=["customer_id", "due_date", "invoice_id"]
    ).reset_index(drop=True)

    # Sort payments: chronological order, tie-break by payment_id.
    payments = payments.sort_values(
        by=["customer_id", "paid_ts", "payment_id"]
    ).reset_index(drop=True)

    # Working state, in integer cents to avoid floating point drift.
    open_amount_cents = {
        int(row.invoice_id): _to_cents(row.amount) for row in invoices.itertuples()
    }

    invoices_by_customer = (
        invoices.groupby("customer_id")["invoice_id"]
        .apply(lambda s: [int(x) for x in s.tolist()])
        .to_dict()
    )

    allocations = []  # list of (payment_id, invoice_id, applied_amount_cents)
    credit_cents = {}  # customer_id -> unapplied cents

    payments_by_customer = payments.groupby("customer_id", sort=False)

    for cust_id, pay_group in payments_by_customer:
        inv_list = invoices_by_customer.get(int(cust_id), [])
        for prow in pay_group.itertuples():
            left = _to_cents(prow.amount)
            pid = int(prow.payment_id)
            if left <= 0:
                continue
            for iid in inv_list:
                if left <= 0:
                    break
                oa = open_amount_cents.get(iid, 0)
                if oa <= 0:
                    continue
                pay = left if left < oa else oa
                open_amount_cents[iid] = oa - pay
                left -= pay
                allocations.append((pid, iid, pay))
            if left > 0:
                credit_cents[int(cust_id)] = credit_cents.get(int(cust_id), 0) + left

    # Total applied per invoice (for status determination).
    applied_total_cents = {}
    for pid, iid, amt in allocations:
        applied_total_cents[iid] = applied_total_cents.get(iid, 0) + amt

    status_rows = []
    for row in invoices.itertuples():
        iid = int(row.invoice_id)
        oa_cents = open_amount_cents[iid]
        applied = applied_total_cents.get(iid, 0)
        if oa_cents == 0:
            status = "PAID"
        elif applied == 0:
            status = "OPEN"
        else:
            status = "PARTIAL"
        status_rows.append((iid, oa_cents / 100.0, status))

    invoice_status = pd.DataFrame(
        status_rows, columns=["invoice_id", "open_amount", "status"]
    )
    if len(invoice_status) == 0:
        invoice_status = pd.DataFrame(
            {
                "invoice_id": pd.Series(dtype="int64"),
                "open_amount": pd.Series(dtype="float64"),
                "status": pd.Series(dtype="object"),
            }
        )
    else:
        invoice_status["invoice_id"] = invoice_status["invoice_id"].astype("int64")
        invoice_status["open_amount"] = invoice_status["open_amount"].astype("float64")
        invoice_status["status"] = invoice_status["status"].astype("object")

    allocations_rows = [
        (pid, iid, amt / 100.0) for (pid, iid, amt) in allocations
    ]
    allocations_df = pd.DataFrame(
        allocations_rows, columns=["payment_id", "invoice_id", "applied_amount"]
    )
    if len(allocations_df) == 0:
        allocations_df = pd.DataFrame(
            {
                "payment_id": pd.Series(dtype="int64"),
                "invoice_id": pd.Series(dtype="int64"),
                "applied_amount": pd.Series(dtype="float64"),
            }
        )
    else:
        allocations_df["payment_id"] = allocations_df["payment_id"].astype("int64")
        allocations_df["invoice_id"] = allocations_df["invoice_id"].astype("int64")
        allocations_df["applied_amount"] = allocations_df["applied_amount"].astype(
            "float64"
        )

    credit_rows = [
        (cust, amt / 100.0) for cust, amt in credit_cents.items() if amt > 0
    ]
    customer_credit = pd.DataFrame(
        credit_rows, columns=["customer_id", "unapplied_amount"]
    )
    if len(customer_credit) == 0:
        customer_credit = pd.DataFrame(
            {
                "customer_id": pd.Series(dtype="int64"),
                "unapplied_amount": pd.Series(dtype="float64"),
            }
        )
    else:
        customer_credit["customer_id"] = customer_credit["customer_id"].astype("int64")
        customer_credit["unapplied_amount"] = customer_credit[
            "unapplied_amount"
        ].astype("float64")

    return {
        "invoice_status": invoice_status,
        "allocations": allocations_df,
        "customer_credit": customer_credit,
    }
